<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$hid=(int)$_POST['hilang'];$fid=(int)$_POST['temuan'];$score=(float)$_POST['skor'];$s=$koneksi->prepare("INSERT INTO matching(id_laporan_hilang,id_laporan_temuan,skor) VALUES(?,?,?) ON DUPLICATE KEY UPDATE skor=VALUES(skor),status='kandidat'");$s->bind_param('iid',$hid,$fid,$score);$s->execute();flash('Kandidat pencocokan disimpan.');redirect('admin/matching.php');}$pageTitle='Pencocokan Barang';$lost=$koneksi->query("SELECT id_laporan,nama_barang FROM laporan WHERE jenis_laporan='hilang' AND moderation_status='aktif'");$found=$koneksi->query("SELECT id_laporan,nama_barang FROM laporan WHERE jenis_laporan='ditemukan' AND moderation_status='aktif'");$rows=$koneksi->query('SELECT m.*,a.nama_barang AS hilang,b.nama_barang AS temuan FROM matching m JOIN laporan a ON a.id_laporan=m.id_laporan_hilang JOIN laporan b ON b.id_laporan=m.id_laporan_temuan ORDER BY m.created_at DESC');require __DIR__.'/../includes/header.php';?><div class="section-grid"><div class="panel"><h2>Buat kandidat pencocokan</h2><p class="muted" style="font-size:11px">Pilih laporan kehilangan dan laporan temuan yang diduga berkaitan.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><div class="field"><label>Laporan barang hilang</label><select name="hilang" required><?php while($x=$lost->fetch_assoc()):?><option value="<?=$x['id_laporan']?>"><?=e($x['nama_barang'])?> (#<?=$x['id_laporan']?>)</option><?php endwhile;?></select></div><div class="field"><label>Laporan barang ditemukan</label><select name="temuan" required><?php while($x=$found->fetch_assoc()):?><option value="<?=$x['id_laporan']?>"><?=e($x['nama_barang'])?> (#<?=$x['id_laporan']?>)</option><?php endwhile;?></select></div><div class="field"><label>Skor kecocokan (0-100)</label><input type="number" min="0" max="100" step="0.1" name="skor" value="75" required></div><button class="btn">Simpan kandidat</button></form></div><div class="panel"><h2>Hasil pencocokan</h2><?php while($r=$rows->fetch_assoc()):?><div class="item"><div class="item-thumb">⇄</div><div class="item-info"><b><?=e($r['hilang'])?> ↔ <?=e($r['temuan'])?></b><small>Skor <?=e($r['skor'])?>% · <?=e($r['status'])?></small></div></div><?php endwhile;?></div></div><?php require __DIR__.'/../includes/footer.php';?>
